//! Pure-Rust re-implementation of the `inflection` C++ library's
//! `Inflector` API, matching its observable behavior byte-for-byte.
//!
//! All functions operate on raw bytes (`&[u8]`) because the original
//! library works on `std::string` with C-locale `toupper`/`tolower`
//! semantics: only ASCII bytes are ever modified, and multi-byte UTF-8
//! sequences pass through (or are dropped, depending on the function).

pub mod case;
pub mod number;
pub mod plural;
pub mod text;

/// Stateless inflector mirroring `inflection::Inflector`.
pub struct Inflector;

impl Inflector {
    /// No-op, kept for API parity with `Inflector::initialize()`.
    pub fn initialize() {}

    /// Append "s" to the word; an empty word stays empty.
    pub fn pluralize(word: &[u8]) -> Vec<u8> {
        plural::pluralize(word)
    }

    /// `true` when the word ends with a lowercase 's'.
    pub fn is_plural(word: &[u8]) -> bool {
        plural::is_plural(word)
    }

    /// English ordinal suffix for an integer ("1st", "2nd", "11th", ...).
    pub fn ordinalize(num: i32) -> Vec<u8> {
        number::ordinalize(num)
    }

    /// Join underscore-separated segments, uppercasing the first byte of
    /// each segment; with `lower_first` the very first byte is left as-is.
    pub fn camelize(word: &[u8], lower_first: bool) -> Vec<u8> {
        case::camelize(word, lower_first)
    }

    /// Uppercase the first byte of every space-separated word, lowercase
    /// the remaining bytes.
    pub fn titleize(word: &[u8]) -> Vec<u8> {
        case::titleize(word)
    }

    /// Uppercase the first byte, lowercase the rest.
    pub fn capitalize(word: &[u8]) -> Vec<u8> {
        case::capitalize(word)
    }

    /// Shorten to `length` bytes, replacing the tail with `omission`.
    pub fn truncate(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
        text::truncate(word, length, omission)
    }

    /// Lowercase ASCII alphanumerics, map spaces to `separator`, drop
    /// every other byte, and trim separators from both ends.
    pub fn parameterize(word: &[u8], separator: &[u8]) -> Vec<u8> {
        text::parameterize(word, separator)
    }
}

//! Naive pluralization matching the C++ library: just append "s".

/// `pluralize("")` yields `""`; anything else gets "s" appended,
/// regardless of how the word ends.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    if word.is_empty() {
        return Vec::new();
    }
    let mut out = word.to_vec();
    out.push(b's');
    out
}

/// A word counts as plural when its last byte is a lowercase 's'.
pub fn is_plural(word: &[u8]) -> bool {
    word.last() == Some(&b's')
}

//! Ordinal suffixes, replicating the C++ integer-remainder semantics
//! (negative remainders never match, so all negative numbers get "th").

pub fn ordinalize(num: i32) -> Vec<u8> {
    let rem100 = num % 100;
    let suffix = if (11..=13).contains(&rem100) {
        "th"
    } else {
        match num % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        }
    };
    format!("{}{}", num, suffix).into_bytes()
}

/// Replicates `std::atoi` on glibc: skip C-locale whitespace, read an
/// optional sign and decimal digits, saturate at `long` range (i64),
/// then truncate to `int` (i32) with wrap-around.
pub fn atoi(bytes: &[u8]) -> i32 {
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut magnitude: u64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        magnitude = magnitude
            .saturating_mul(10)
            .saturating_add((bytes[i] - b'0') as u64);
        i += 1;
    }

    // strtol clamps to LONG_MAX / LONG_MIN on overflow.
    let value: i64 = if negative {
        if magnitude > i64::MAX as u64 {
            i64::MIN
        } else {
            -(magnitude as i64)
        }
    } else if magnitude > i64::MAX as u64 {
        i64::MAX
    } else {
        magnitude as i64
    };

    // (int)strtol(...) — wrapping truncation, like the C cast.
    value as i32
}

//! Case transformations. All of them are byte-oriented with C-locale
//! semantics: only ASCII letters change case, everything else passes
//! through untouched.

/// Split on '_', uppercase the first byte of each segment, drop the
/// underscores. When `lower_first` is set, the first byte of the input
/// is emitted unchanged (empty leading segments still force an
/// uppercase on the first real byte, matching the C++ state machine).
pub fn camelize(word: &[u8], lower_first: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut upper_next = !lower_first;
    for &b in word {
        if b == b'_' {
            upper_next = true;
            continue;
        }
        if upper_next {
            out.push(b.to_ascii_uppercase());
            upper_next = false;
        } else {
            out.push(b);
        }
    }
    out
}

/// Words are delimited by the space byte only; the first byte of each
/// word is uppercased and every other byte lowercased.
pub fn titleize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut word_start = true;
    for &b in word {
        if b == b' ' {
            out.push(b);
            word_start = true;
        } else if word_start {
            out.push(b.to_ascii_uppercase());
            word_start = false;
        } else {
            out.push(b.to_ascii_lowercase());
        }
    }
    out
}

/// Uppercase the first byte, lowercase all remaining bytes.
pub fn capitalize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for (i, &b) in word.iter().enumerate() {
        if i == 0 {
            out.push(b.to_ascii_uppercase());
        } else {
            out.push(b.to_ascii_lowercase());
        }
    }
    out
}

//! Text helpers: byte-based truncation and URL-style parameterization.

/// If the word fits in `length` bytes it is returned unchanged;
/// otherwise the result is the first `length - omission.len()` bytes
/// followed by `omission`. The cut is purely byte-based and may split
/// a multi-byte UTF-8 sequence, exactly like `std::string::substr`.
pub fn truncate(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
    if word.len() <= length {
        return word.to_vec();
    }
    // Mirrors substr(0, length - omission.length()) with size_t
    // wrap-around: an underflowing count clamps to the whole string.
    let keep = if length >= omission.len() {
        (length - omission.len()).min(word.len())
    } else {
        word.len()
    };
    let mut out = word[..keep].to_vec();
    out.extend_from_slice(omission);
    out
}

/// Keep ASCII alphanumerics (lowercased), map each space byte to
/// `separator`, drop every other byte (including all non-ASCII bytes),
/// then strip separators from both ends. Separators are not collapsed.
pub fn parameterize(word: &[u8], separator: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for &b in word {
        if b.is_ascii_alphanumeric() {
            out.push(b.to_ascii_lowercase());
        } else if b == b' ' {
            out.extend_from_slice(separator);
        }
    }

    if !separator.is_empty() {
        while out.starts_with(separator) {
            out.drain(..separator.len());
        }
        while out.ends_with(separator) {
            out.truncate(out.len() - separator.len());
        }
    }
    out
}

//! Port of tests/test11.cpp from the inflection-cpp project.
//!
//! Usage: test11 <number> <word>
//! Prints the results of 11 Inflector API calls, one per line.

mod inflection;

use inflection::Inflector;
use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn push_line(out: &mut Vec<u8>, line: &[u8]) {
    out.extend_from_slice(line);
    out.push(b'\n'); // std::endl
}

fn main() {
    Inflector::initialize();

    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    if args.len() > 2 {
        let num = inflection::number::atoi(args[1].as_bytes());
        let word = args[2].as_bytes();

        // Build the whole output as raw bytes: truncate() may cut a
        // multi-byte UTF-8 sequence, which a String cannot represent.
        let mut out = Vec::new();
        push_line(&mut out, &Inflector::pluralize(word));
        push_line(&mut out, &Inflector::ordinalize(num));
        push_line(&mut out, &Inflector::camelize(word, true));
        push_line(&mut out, &Inflector::camelize(word, false));
        push_line(&mut out, &Inflector::titleize(word));
        push_line(&mut out, &Inflector::capitalize(word));
        push_line(&mut out, &Inflector::truncate(word, 5, b"..."));
        push_line(&mut out, &Inflector::truncate(word, 10, b"~"));
        push_line(&mut out, &Inflector::parameterize(word, b"-"));
        push_line(&mut out, &Inflector::parameterize(word, b"_"));
        let plural: &[u8] = if Inflector::is_plural(word) { b"1" } else { b"0" };
        push_line(&mut out, plural);

        std::io::stdout().write_all(&out).unwrap();
    }
}
